// break termina el bucle INMEDIATAMENTE
for (int i = 0; i < 10; i++)
{
    if (i == 5)
        break;  // Sale del bucle cuando i es 5
    Debug.Log(i);  // Imprime: 0, 1, 2, 3, 4
}
// La ejecución continúa AQUÍ después del break

// continue salta a la siguiente iteración
for (int i = 0; i < 5; i++)
{
    if (i == 2)
        continue;  // Salta cuando i es 2
    Debug.Log(i);  // Imprime: 0, 1, 3, 4  (el 2 se omite)
}
// El bucle CONTINÚA — solo se saltan las iteraciones marcadas

En Unity es muy común usar <strong>continue</strong> para saltarse enemigos muertos en un loop:<br><pre>foreach (Enemy e in enemies) {
    if (e.IsDead) continue;  // Ignora muertos
    e.UpdateAI();            // Solo procesa vivos
}</pre><br>Y <strong>break</strong> para encontrar el primer enemigo cercano y dejar de buscar:<br><pre>Enemy nearest = null;
foreach (Enemy e in enemies) {
    if (Vector3.Distance(transform.position, e.transform.position) < 5f) {
        nearest = e;
        break;  // Encontramos uno, no necesitamos seguir
    }
}</pre>

